SELECT C.*, , , ,
FROM WORK_EFFORT_TYPE WET INNER JOIN WORK_EFFORT_TYPE_CONTENT WETC ON WET.WORK_EFFORT_TYPE_ID = WETC.WORK_EFFORT_TYPE_ID LEFT OUTER JOIN WORK_EFFORT_ANALYSIS WEA ON WEA.WORK_EFFORT_TYPE_ID = WETC.WORK_EFFORT_TYPE_ID INNER JOIN CONTENT C ON WETC.CONTENT_ID = C.CONTENT_ID INNER JOIN DATA_RESOURCE DR ON DR.DATA_RESOURCE_ID = C.DATA_RESOURCE_ID WHERE C.CONTENT_ID = #{reportContentId} AND WET.PARENT_TYPE_ID = #{parentTypeId}
AND WETC.WORK_EFFORT_TYPE_ID = #{workEffortTypeId}
AND WETC.WORK_EFFORT_TYPE_ID is not null
ORDER BY WETC.SEQUENCE_NUM ASC

SELECT C.*, ,

FROM WORK_EFFORT_TYPE WET
INNER JOIN WORK_EFFORT_ANALYSIS WEA ON WET.WORK_EFFORT_TYPE_ID = WEA.WORK_EFFORT_TYPE_ID
INNER JOIN CONTENT C ON WEA.REPORT_ID = C.CONTENT_ID
WHERE WET.PARENT_TYPE_ID = #{parentTypeId}
AND C.CONTENT_ID = #{reportContentId}
AND WEA.DESCRIPTION5 = #{reportName} OR C.DESCRIPTION = #{reportName}
AND WEA.DESCRIPTION5 IN NULL
